-- ----------------------------
-- View structure for v_alarminfo
-- ----------------------------
DROP VIEW IF EXISTS `v_alarminfo`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_alarminfo` AS select `aa`.`task_id` AS `id`,`aa`.`create_time` AS `updatetime`,`bb`.`dvr_name` AS `dvrname`,(case when (`aa`.`devid` = '') then 'D5000' else `aa`.`devid` end) AS `devname`,`bb`.`ip` AS `dvrip`,`aa`.`devchannel` AS `dvrchannel`,concat(`ff`.`device`,' ',`ff`.`info`) AS `desc`,`aa`.`filename` AS `hisvideo`,`ee`.`realserialnum` AS `realvideo`,`aa`.`shortvideo` AS `shortvideo`,`hh`.`stationname` AS `station`,`gg`.`roomname` AS `roomname` from ((((((`m_task` `aa` left join `m_devinfo` `cc` on((`cc`.`devid` = `aa`.`devid`))) left join `m_camera` `ee` on((`ee`.`camera_id` = `aa`.`camera_id`))) left join `m_dvr` `bb` on((`bb`.`dvr_id` = `ee`.`dvr_id`))) left join `m_info` `ff` on((`ff`.`info_id` = `aa`.`info_id`))) left join `m_stationroom` `gg` on((`gg`.`id` = `ee`.`roomid`))) left join `m_stationinfo` `hh` on((`hh`.`id` = `gg`.`stationid`)));

-- ----------------------------
-- View structure for v_curalert
-- ----------------------------
DROP VIEW IF EXISTS `v_curalert`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_curalert` AS select `aa`.`task_id` AS `id`,`aa`.`sts` AS `sts`,`aa`.`create_time` AS `updatetime`,`bb`.`camera_name` AS `camera_name`,`cc`.`roomname` AS `roomname`,`dd`.`stationname` AS `stationname`,(case when (`aa`.`devid` = '') then '0' else '1' end) AS `type`,`aa`.`opsts` AS `opsts`,`aa`.`errortype` AS `errortype` from (((`m_task` `aa` left join `m_camera` `bb` on((`aa`.`camera_id` = `bb`.`camera_id`))) left join `m_stationroom` `cc` on((`bb`.`roomid` = `cc`.`id`))) left join `m_stationinfo` `dd` on((`cc`.`stationid` = `dd`.`id`)));

-- ----------------------------
-- View structure for v_dvrcamlist
-- ----------------------------
DROP VIEW IF EXISTS `v_dvrcamlist`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_dvrcamlist` AS select `aa`.`camera_name` AS `camera_name`,`aa`.`channel` AS `channel`,`bb`.`dvr_id` AS `dvr_id`,`bb`.`dvr_name` AS `dvr_name`,`bb`.`ip` AS `ip`,`bb`.`port` AS `port`,`bb`.`user` AS `user`,`bb`.`pwd` AS `pwd`,`bb`.`is_need_trans` AS `is_need_trans`,`bb`.`sts` AS `sts`,`bb`.`stationid` AS `stationid`,`bb`.`create_time` AS `create_time` from (`m_camera` `aa` left join `m_dvr` `bb` on((`aa`.`dvr_id` = `bb`.`dvr_id`))) order by ((0 <> `aa`.`dvr_id`) and (0 <> `aa`.`channel`));

-- ----------------------------
-- View structure for v_errlist
-- ----------------------------
DROP VIEW IF EXISTS `v_errlist`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_errlist` AS select `aa`.`id` AS `id`,`dv`.`ip` AS `nvrip`,`aa`.`nvrport` AS `nvrport`,`aa`.`nvruser` AS `nvruser`,`aa`.`nvrpasswd` AS `nvrpasswd`,`aa`.`nvrchannel` AS `nvrchannel`,(case when (`aa`.`state` = '0') then '检测中' when (`aa`.`state` = '1') then '检测正常' when (`aa`.`state` = '2') then '检测提示' when (`aa`.`state` = '3') then '检测告警' when (`aa`.`state` = '4') then '下载图像失败' end) AS `stateval`,`aa`.`state` AS `state`,(case when (`aa`.`devid` = 'bj200100') then '系统任务' else '检测终端' end) AS `taskfrom`,`aa`.`errortype` AS `errortype`,`aa`.`errorimg` AS `errorimg`,`aa`.`flag` AS `flag`,`aa`.`gifname` AS `gifname`,`aa`.`errdatetime` AS `updatetime`,`bb`.`dvrchannel` AS `dvrchannel`,`cc`.`camera_id` AS `camera_id`,`cc`.`camera_name` AS `camera_name`,`cc`.`roomid` AS `roomid`,`dd`.`roomname` AS `roomname`,`ee`.`stationname` AS `stationname`,(case when (`aa`.`state` = '3') then (select `m_modelinfo`.`errtypename` from `m_modelinfo` where (`m_modelinfo`.`errtypeindex` = `aa`.`errortype`)) when (`aa`.`state` = '0') then '检测中' when (`aa`.`state` = '1') then '无异常' else '检测异常' end) AS `meaning`,`aa`.`optflag1` AS `optflag1`,`aa`.`confirm` AS `confirm` from ((((`m_dvr` `dv` left join (`m_errorinfo` `aa` left join `m_devrunconfig` `bb` on(((`aa`.`devid` = `bb`.`devid`) and (`aa`.`nvrchannel` = `bb`.`devchannel`)))) on(((`dv`.`dvr_id` = `bb`.`dvrinfoid`) and (`aa`.`nvrip` = `dv`.`ip`)))) left join `m_camera` `cc` on(((`bb`.`dvrinfoid` = `cc`.`dvr_id`) and (`bb`.`dvrchannel` = `cc`.`channel`)))) left join `m_stationroom` `dd` on((`dd`.`id` = `cc`.`roomid`))) left join `m_stationinfo` `ee` on((`ee`.`id` = `dd`.`stationid`))) order by `aa`.`errdatetime` desc;

-- ----------------------------
-- View structure for v_historyalarm
-- ----------------------------
DROP VIEW IF EXISTS `v_historyalarm`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_historyalarm` AS select `aa`.`task_id` AS `id`,`aa`.`sts` AS `sts`,`cc`.`stationid` AS `stationid`,`aa`.`camera_id` AS `camid`,`aa`.`create_time` AS `updatetime`,`bb`.`camera_name` AS `cameraname`,`cc`.`roomname` AS `roomname`,`dd`.`stationname` AS `stationname`,(case when (`aa`.`devid` = '') then '0' else '1' end) AS `type`,`aa`.`opsts` AS `opsts`,`aa`.`errortype` AS `errortype` from (((`m_task` `aa` left join `m_camera` `bb` on(((`aa`.`camera_id` = `bb`.`camera_id`) and (`aa`.`opsts` = 20)))) left join `m_stationroom` `cc` on((`bb`.`roomid` = `cc`.`id`))) left join `m_stationinfo` `dd` on((`cc`.`stationid` = `dd`.`id`))) order by `aa`.`task_id` desc;

-- ----------------------------
-- View structure for v_overhaularea
-- ----------------------------
DROP VIEW IF EXISTS `v_overhaularea`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_overhaularea` AS with recursive `split_rooms` as (select `m_overhaularea`.`id` AS `id`,`j`.`room_id` AS `room_id`,`m_overhaularea`.`starttime` AS `starttime`,`m_overhaularea`.`endtime` AS `endtime` from (`m_overhaularea` join json_table(concat('["',replace(`m_overhaularea`.`roomids`,',','","'),'"]'), '$[*]' columns (`room_id` varchar(50) character set utf8mb4 path '$')) `j`)), `sorted_maintain` as (select `split_rooms`.`room_id` AS `room_id`,`split_rooms`.`starttime` AS `starttime`,`split_rooms`.`endtime` AS `endtime`,row_number() OVER (PARTITION BY `split_rooms`.`room_id` ORDER BY `split_rooms`.`starttime` )  AS `rn` from `split_rooms`), `merged_maintain` as (select `sorted_maintain`.`room_id` AS `room_id`,`sorted_maintain`.`starttime` AS `starttime`,`sorted_maintain`.`endtime` AS `endtime`,`sorted_maintain`.`rn` AS `rn` from `sorted_maintain` where (`sorted_maintain`.`rn` = 1) union all select `m`.`room_id` AS `room_id`,least(`m`.`starttime`,`s`.`starttime`) AS `LEAST(m.starttime, s.starttime)`,greatest(`m`.`endtime`,`s`.`endtime`) AS `GREATEST(m.endtime, s.endtime)`,`s`.`rn` AS `rn` from (`merged_maintain` `m` join `sorted_maintain` `s` on(((`m`.`room_id` = `s`.`room_id`) and (`s`.`rn` = (`m`.`rn` + 1)) and (`s`.`starttime` <= `m`.`endtime`))))) select `t`.`room_id` AS `room_id`,`t`.`starttime` AS `merged_start`,`t`.`endtime` AS `merged_end` from (select `merged_maintain`.`room_id` AS `room_id`,`merged_maintain`.`starttime` AS `starttime`,`merged_maintain`.`endtime` AS `endtime`,row_number() OVER (PARTITION BY `merged_maintain`.`room_id` ORDER BY `merged_maintain`.`rn` desc )  AS `rn_desc` from `merged_maintain`) `t` where (`t`.`rn_desc` = 1) order by `t`.`room_id`,`t`.`starttime`;

SET FOREIGN_KEY_CHECKS = 1;
